function parseCSV(text: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let field = '';
  let inQuotes = false;

  for (let i = 0; i < text.length; i++) {
    const c = text.charAt(i);
    if (inQuotes) {
      if (c === '"') {
        if (text.charAt(i + 1) === '"') {
          field += '"';
          i++;
        } else {
          inQuotes = false;
        }
      } else {
        field += c;
      }
    } else {
      if (c === '"') {
        inQuotes = true;
      } else if (c === ',') {
        row.push(field);
        field = '';
      } else if (c === '\n') {
        row.push(field);
        rows.push(row);
        row = [];
        field = '';
      } else if (c === '\r') {
        // ignore
      } else {
        field += c;
      }
    }
  }

  if (field.length > 0 || row.length > 0) {
    row.push(field);
    rows.push(row);
  }

  return rows;
}

function formatWithCommas(num: number, decimals: number): string {
  const fixed = num.toFixed(decimals);
  const dot = fixed.indexOf('.');
  let intPart = dot >= 0 ? fixed.substring(0, dot) : fixed;
  const decPart = dot >= 0 ? fixed.substring(dot + 1) : '';
  let sign = '';

  if (intPart.charAt(0) === '-') {
    sign = '-';
    intPart = intPart.substring(1);
  }

  let result = '';
  for (let i = 0; i < intPart.length; i++) {
    if (i > 0 && (intPart.length - i) % 3 === 0) {
      result += ',';
    }
    result += intPart.charAt(i);
  }

  if (decimals > 0) {
    return sign + result + '.' + decPart;
  }
  return sign + result;
}

