        self.skip_ws();
        match self.peek()? {
            b'n' => {
                self.i += 4;
                Some(Json::Null)
            }
            b't' => {
                self.i += 4;
                Some(Json::Bool(true))
            }
            b'f' => {
                self.i += 5;
                Some(Json::Bool(false))
            }
