func lineCount(_ data: Data) -> Int {
    if data.isEmpty { return 0 }
    var count = 0
    data.withUnsafeBytes { rawBuffer in
        let bytes = rawBuffer.bindMemory(to: UInt8.self)
        for b in bytes {
            if b == 0x0A { count += 1 }
        }
        if let last = bytes.last, last != 0x0A {
            count += 1
        }
    }
    return count
}

func walk(_ dir: URL) {
    guard let contents = try? fm.contentsOfDirectory(
        at: dir,
        includingPropertiesForKeys: [.isSymbolicLinkKey, .isDirectoryKey, .isRegularFileKey],
        options: []
    ) else { return }

    for url in contents {
        let stdURL = url.standardizedFileURL
        let values = try? stdURL.resourceValues(forKeys: [.isSymbolicLinkKey, .isDirectoryKey, .isRegularFileKey])

        if values?.isSymbolicLink == true { continue }

        if values?.isDirectory == true {
            walk(stdURL)
        } else if values?.isRegularFile == true {
            guard let data = try? Data(contentsOf: stdURL) else { continue }

            let chars = data.count
            let lines = lineCount(data)
            let extRaw = stdURL.pathExtension
            let ext = extRaw.isEmpty ? "(none)" : "." + extRaw

            let prefix = baseURL.path.hasSuffix("/") ? baseURL.path : baseURL.path + "/"
            let relPath: String
            if stdURL.path.hasPrefix(prefix) {
                relPath = String(stdURL.path.dropFirst(prefix.count))
            } else {
                relPath = stdURL.lastPathComponent
            }

            fileRecords.append((ext: ext, relPath: relPath, lines: lines, chars: chars))
        }
    }
}

