fn count_file(path: &Path) -> io::Result<(u64, u64)> {
    let mut file = fs::File::open(path)?;
    let mut buf = [0u8; 8192];
    let mut chars = 0u64;
    let mut lines = 0u64;
    let mut last = None;

    loop {
        let n = file.read(&mut buf)?;
        if n == 0 {
            break;
        }
        chars += n as u64;
        for &b in &buf[..n] {
            if b == b'\n' {
                lines += 1;
            }
            last = Some(b);
        }
    }

    if chars > 0 && last != Some(b'\n') {
        lines += 1;
    }

    Ok((lines, chars))
}

fn walk_dir(dir: &Path, base: &Path, map: &mut BTreeMap<String, Vec<FileInfo>>) -> io::Result<()> {
    for entry in fs::read_dir(dir)? {
        let entry = entry?;
        let path = entry.path();
        let meta = fs::symlink_metadata(&path)?;
        let ft = meta.file_type();

        if ft.is_symlink() {
            continue;
        }

        if ft.is_dir() {
            walk_dir(&path, base, map)?;
        } else if ft.is_file() {
            let rel = path
                .strip_prefix(base)
                .unwrap()
                .to_string_lossy()
                .replace('\\', "/");

            let (lines, chars) = count_file(&path)?;

            let ext = match path.extension() {
                Some(e) => format!(".{}", e.to_string_lossy()),
                None => "(none)".to_string(),
            };

            map.entry(ext).or_default().push(FileInfo {
                rel,
                lines,
                chars,
            });
        }
    }

    Ok(())
}

