use std::process::Command;

fn run(cmd: &str, args: &[&str]) -> String {
    let out = Command::new(cmd)
        .args(args)
        .output()
        .expect("failed to execute command");
    String::from_utf8_lossy(&out.stdout).trim().to_string()
}

fn escape(s: &str) -> String {
    let mut r = String::new();
    for c in s.chars() {
        match c {
            '"' => r.push_str("\\\""),
            '\\' => r.push_str("\\\\"),
            '\n' => r.push_str("\\n"),
            '\r' => r.push_str("\\r"),
            '\t' => r.push_str("\\t"),
            c if (c as u32) < 0x20 => r.push_str(&format!("\\u{:04x}", c as u32)),
            c => r.push(c),
        }
    }
    r
}

fn main() {
    let hostname = run("hostname", &[]);
    let os = run("uname", &["-s"]);
    let architecture = run("uname", &["-m"]);
    let username = run("whoami", &[]);

    println!("{{");
    println!("  \"hostname\": \"{}\",", escape(&hostname));
    println!("  \"os\": \"{}\",", escape(&os));
    println!("  \"architecture\": \"{}\",", escape(&architecture));
    println!("  \"username\": \"{}\"", escape(&username));
    println!("}}");
}

