func multiply(_ a: [[Int]], _ b: [[Int]]) -> [[Int]] {
    let rows = a.count
    let cols = b[0].count
    let inner = b.count
    var result = Array(repeating: Array(repeating: 0, count: cols), count: rows)

    for i in 0..<rows {
        for j in 0..<cols {
            var sum = 0
            for k in 0..<inner {
                sum += a[i][k] * b[k][j]
            }
            result[i][j] = sum
        }
    }

    return result
}

func determinant3(_ m: [[Int]]) -> Int {
    let a = m[0][0], b = m[0][1], c = m[0][2]
    let d = m[1][0], e = m[1][1], f = m[1][2]
    let g = m[2][0], h = m[2][1], i = m[2][2]

    return a * (e * i - f * h)
        - b * (d * i - f * g)
        + c * (d * h - e * g)
}

